/* All inference runs in this worker; tar requests can only use explicitly prepared cache. */
const originalFetch=self.fetch.bind(self);
self.fetch=async(input,init)=>{const u=new URL(typeof input==='string'?input:input.url,self.location.href);if(u.pathname.includes('/models/paddle/')||u.pathname.includes('/vendor/paddle/')){const cached=await (await caches.open('akai-paddle-024')).match(u.href);if(!cached)throw Error('MODEL_NOT_CACHED: PaddleOCR를 모델 관리에서 준비하세요.');return cached}return originalFetch(input,init)};
let instance=null,key='';
self.onmessage=async({data:{id,bitmap,writing}})=>{try{const {PaddleOCR}=await import('./vendor/paddle/sdk.mjs');const rec=writing==='korean'?'korean_PP-OCRv5_mobile_rec':'PP-OCRv5_mobile_rec';if(!instance||key!==rec){await instance?.dispose();instance=null;key='';self.postMessage({id,type:'progress',text:'PaddleOCR 엔진 준비 중…'});instance=await PaddleOCR.create({textDetectionModelName:'PP-OCRv5_mobile_det',textRecognitionModelName:rec,textDetectionModelAsset:{url:new URL('./models/paddle/PP-OCRv5_mobile_det.tar',self.location.href).href},textRecognitionModelAsset:{url:new URL('./models/paddle/'+rec+'.tar',self.location.href).href},ortOptions:{backend:'wasm',numThreads:1,proxy:false,wasmPaths:new URL('./vendor/paddle/',self.location.href).href}});key=rec}self.postMessage({id,type:'progress',text:'PaddleOCR 글자 인식 중…'});const [result]=await instance.predict(bitmap,{textDetLimitSideLen:960,textDetLimitType:'max',textRecScoreThresh:0.15});const items=(result?.items||[]).filter(x=>x.text?.trim());const center=x=>{const p=x.poly||[];return {x:p.reduce((s,a)=>s+a[0],0)/p.length,y:p.reduce((s,a)=>s+a[1],0)/p.length}};if(writing==='vertical')items.sort((a,b)=>{const A=center(a),B=center(b);return Math.abs(A.x-B.x)>15?B.x-A.x:A.y-B.y});const text=items.map(x=>x.text.trim()).join('\n');if(!text)throw Error('글자를 인식하지 못했습니다. 범위와 인식 언어를 확인하세요.');self.postMessage({id,type:'result',text});}catch(e){self.postMessage({id,type:'error',error:String(e.message||e)})}finally{bitmap?.close()}};
